INSERT INTO `tbl_programs` (`program_ID`, `collegeID`, `programName`, `programDescription`, `shortDesc`, `careerPaths`, `programUSTlink`) VALUES
	(15, 19, 'Bachelor of Science in Accountancy', 'Accounting professionals are involved in providing assurance and audit services for statutory financial reporting, tax-related services, management advisory services partnering in management decision-making, devising planning and performance and control systems, and providing expertise in financial reporting and control to assist various stakeholders in making decisions.', 'Accounting professionals offer services like auditing, tax preparation, and management consulting. Their expertise in financial systems assists stakeholders in planning and decision-making.', '["Staff Accountant", "Associate Auditor", "Junior Analyst", "Cost analyst"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-accountancy/'),
	(16, 19, 'Bachelor of Science in Accounting Information System', 'Accounting information system professionals link operational activities, financial resource generation and consumption, value generation and preservation through a well-functioning information system.   They are expected to apply accounting, finance and computer skills in the context of the business, influencing the decisions, actions and behaviours of others and, thus, assisting and/or leading the organization at different levels. ', 'These professionals integrate operational and financial data through information systems to preserve organizational value. By applying expertise in accounting, finance, and technology, they influence business decisions and help lead the organization.', '["Accounting Analyst", "State Auditor", "Data Analyst", "Staff Accountant"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-accounting-information-system/'),
	(17, 19, 'Bachelor of Science in Management Accounting', 'Management accounting is a profession that involves partnering in management decision making, devising planning and performance management systems, and providing expertise in financial accounting and control to assist management in the formulation and implementation of an organizationÃ¢â‚¬â„¢s strategy.', 'Management accountants partner with leadership to aid in strategic decision-making and planning. They provide expertise in financial control and performance systems to help formulate and implement organizational strategy.', '["Credit Analyst", "Cost Analyst", "Junior Analyst", "Cost Accountant"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-management-accounting/'),
	(18, 9, 'Bachelor of Science in Architecture', 'The Bachelor of Science in Architecture being offered is an enhanced five-year program designed to prepare its students to be global architects who will contribute to and influence in the improvement of the built environment. The sequence of the technical and professional courses has been structured to methodically develop the knowledge and skills of the students per year level. The pedagogy for the courses is now dynamic, with mentoring given focus in its delivery. To ensure intensive stimulation of student creativity and skill, the Faculty-Student ratio for the Design and Building Technology courses is now 1:23. The Architecture Midterm Aptitude Comprehensive Examination and the Architecture Review Course given to 3rd and 5th year students, respectively, validates the knowledge gained by the students about the program. Linkages with foreign universities and organizations provides opportunities for the students for international exposure. In their final year, students harvest all their learnings and showcase everything through their thesis project.', 'This five-year architecture program prepares students to become "global" architects who improve the built environment through a structured, mentored curriculum. It emphasizes developing creativity and skills with a low student-teacher ratio, comprehensive exams, international exposure, and a culminating thesis project.', '["CADD Operator", "Project Coordinator", "Scale Modeling", "Architectural Drafting"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-architecture/'),
	(19, 1, 'Bachelor of Arts in Behavioral Science', 'The Bachelor of Arts in Behavioral Science (BES) program combines psychology, management, and sociology, with emphasis on human resource management. ', 'This program integrates psychology, sociology, and management to study human behavior. It places a particular emphasis on the principles of human resource management.', '["HR Manager", "Organization Analyst", "Employee Relations Specialist", "Training Manager"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-arts-in-behavioral-science/'),
	(20, 1, 'Bachelor of Arts in Political Science', 'The undergraduate program in Political Science provides its students with excellent training in the discipline through instruction, research, and internship. The new curriculum was the result of the series of consultations with the faculty, students, alumni, and industry in 2017. The courses are concentrated on five (5) primary fields: 1) Philippine government and politics; 2) Comparative politics; 3) International relations; 4) Political theory; and 5) Public administration. ', 'This Political Science program provides comprehensive training through instruction, research, and an internship. Its curriculum, developed from wide consultations, focuses on five core fields including Philippine politics, international relations, and public administration.', '["Law", "Pulic Service", "Civil Service", "Public Relations"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-arts-in-political-science/'),
	(21, 1, 'Bachelor of Arts in Economics', 'The program is designed to equip students with knowledge in economic theory and its application and with essential skills for undertaking economic analysis. Intended to provide students with a more liberal education, the BA program requires fewer major (Economics) courses but more liberal arts, such as those in humanities, other social sciences, and foreign languages. The BA curriculum is more flexible, giving students leeway to customize their program of study according to their personal goals and interests. ', 'This Bachelor of Arts in Economics program teaches economic theory and analytical skills while providing a broad liberal arts education. Its flexible curriculum allows students to customize their studies with courses in humanities and other social sciences.', '["Management Trainee", "Credit and Collections Staff", "Commodity Analyst", "Financial Analyst"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-arts-in-economics/'),
	(22, 10, 'Bachelor of Science in Entrepreneurship', 'The BS Entrepreneurship program is primarily designed to provide training to would-be entrepreneurs in the nuances of starting and operating a business as well as building oneÃ¢â‚¬â„¢s character. The program commits itself to the education and formation of students who will be competent, committed, and compassionate entrepreneurs imbued with ethical, pro-social, and altruistic qualities of empathy, social responsibility, and justice.', 'This program trains students in the practical aspects of starting and running a business while emphasizing character development. It aims to produce competent and compassionate entrepreneurs guided by strong ethics and social responsibility.', '["Marketing Assistant", "Corporate Planning Assistant"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-entrepreneurship/'),
	(23, 10, 'Bachelor of Science in Business Administration, major in Marketing Management', 'The Bachelor of Science in Business Administration, major in Marketing Management program produces well-rounded, globally competitive graduates equipped with the knowledge to cover specific areas in marketing, such as marketing research, distribution management, product management, brand management, personal selling, pricing management, and Internet management in order to meet the needs of the changing environment in the business world.', 'This marketing program equips graduates with comprehensive knowledge in areas like market research and brand management to be globally competitive. It prepares them to adapt and meet the demands of a constantly evolving business environment.', '["Sales Associate", "Marketing Analyst", "Product/Brand Assistant", "Marketing Manager"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-business-administration-major-in-marketing-management/'),
	(24, 10, 'Bachelor of Science in Business Administration, major in Financial Management', 'Bachelor of Science in Business Administration, Major in Financial Management is a four-year degree program that provides students with a strong foundation on theories, principles, and concepts that equip them with relevant technical and analytical skills necessary in financial decision-making, cognizant of a dynamic domestic and global business environments, and mindful of their role in nation-building. The studentsÃ¢â‚¬â„¢ terminal outputs are research undertakings that are geared toward both application of learned concepts and/or theory development.', 'This four-year Financial Management program equips students with the technical and analytical skills for sound financial decision-making in a global business environment. The program culminates in research projects that apply financial concepts and emphasizes the graduate\'s role in nation-building.', '["Financial Analyst", "Investment Researcher", "Equity Analyst", "Fund Manager"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-business-administration-major-in-financial-management/'),
	(25, 11, 'Bachelor of Elementary Education', 'Bachelor of Elementary Education (BEEd) is a four-year program that provides academic and appropriate training for future elementary school teachers of Grades 1 Ã¢â‚¬â€œ 6 through the general education courses, professional education, and specialization courses. The program culminates with an extensive teaching internship in various cooperating schools, both public and private, local and international, under the mentorship of highly experienced professional teachers. ', 'This four-year program trains students to become elementary school teachers through general, professional, and specialized courses. It concludes with a comprehensive teaching internship in various local and international schools under experienced mentors.', '["Primary Teacher", "Intermediate Teacher", "Educational Researcher", "School Director"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-elementary-education/'),
	(26, 11, 'Bachelor of Secondary Education', 'Bachelor of Secondary Education (BSEd) is a four-year program that prepares its students for the art and science of teaching. It builds know-how in pedagogy, such as foundations of education, principles of teaching, facilitating learning, curriculum development, child and adolescent psychology, assessment of student learning, educational technology and instructional materials preparation, and classroom management, among others, as well as would-be teachersÃ¢â‚¬â„¢ disciplinal expertise. The areas of specialization offered by the program are: Science, English, Filipino, Mathematics, Religious and Values Education, and Social Studies. The program culminates with an intensive one-year practice teaching in the laboratory school of the College and in the cooperating public and private (local and international) schools, where student teachers receive active mentoring from highly-experienced professional teachers. ', 'This four-year program prepares students for the science and art of teaching by developing their pedagogical skills and disciplinal expertise in specializations like Science and English. It culminates in a year-long teaching internship with active mentoring in various local and international schools.', '["Grade School Teacher", "Junior High School Teacher", "Researcher", "Coach"]', 'https://www.ust.edu.ph/education/'),
	(27, 11, 'Bachelor of Science in Food Technology', 'Bachelor of Science in Food Technology (BSFT) is a four-year program that integrates the disciplines of the chemistry, biology, and engineering in the innovation and processing of safe, stable, palatable, and nutritious food in order to address growing global food security concerns. The program also provides opportunities to gain managerial and entrepreneurial skills essential for a successful food business. ', 'This four-year program applies chemistry, biology, and engineering to create safe and nutritious food, addressing global security concerns. It also equips students with the managerial and entrepreneurial skills needed for a successful food business.', '["Production Manager", "Product Development Specialist", "Sensory Analyst", "Food Quality Assurance Officer"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-food-technology/'),
	(28, 3, 'Bachelor of Science in Chemical Engineering', 'Bachelor of Science in Chemical Engineering alumni from the University of Santo Tomas shall be engaged either locally or abroad in design, operation, or management of an industrial plant; or  pursue teaching, research, technical sales, or entrepreneurship after having completed advanced studies or special training. Furthermore, they shall be expected to imbibe the Thomasian traits of contemplative, creative, and critical thinking; exemplary work ethic; and a commitment to the improvement of society and lifelong learning. ', 'Graduates of this program are prepared for careers in plant design, management, research, or entrepreneurship, both locally and abroad. They are also expected to become critical thinkers with a strong work ethic and a commitment to societal improvement.', '["Waste Management Expert", "Product Development Engineer", "Quality Control Engineer", "Safety, Health, and Environment Officer"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-chemical-engineering/'),
	(29, 3, 'Bachelor of Science in Civil Engineering', 'The Bachelor of Science in Civil Engineering (CE) Program enables aspiring engineers to develop thinking, collaborative, and technical skills for solving complex civil engineering problems and to learn how to assimilate new knowledge needed for the design, construction, and maintenance of roads, bridges, buildings, water supply, irrigation, flood control, ports, and other infrastructure while considering impact in various contexts. The UST CE Program prepares individuals to engage in any field of civil engineering and, moreover, educates them in any of these specialized fields: Construction and Management Engineering, Geotechnical Engineering, Structural Engineering, Transportation Engineering, and Water Resources Engineering. All graduates imbibe the Thomasian Graduate Attributes that warrant their productivity and ethical participation in society and nation-building through academe, research, and industry practice. ', 'This program develops engineers with the collaborative and technical skills to design, build, and maintain essential infrastructure. It offers specialized fields of study and prepares graduates for productive, ethical careers in industry, research, and nation-building.', '["Geotechnical Engineer", "Environmental Engineer", "Structural / Design Engineer", "Construction Manager / Engineer"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-civil-engineering/'),
	(30, 3, 'Bachelor of Science in Electrical Engineering', 'The Bachelor of Science in Electronics Engineering Program (BS ECE) of the University of Santo Tomas provides a curriculum that allows the students to have wide and deep knowledge in various fields of the Electronics Engineering discipline. The program develops undergraduate students by enabling them to contribute to technological advancement through research and innovation. The UST BS ECE Program offers three (3) specialization tracks, namely: Communications, Microelectronics, and Instrumentation and Control. The Communications track specializes in the area of network design and efficient wireless transmission of multimedia information, while the Microelectronics track specializes in the development of sensors, micro-electromechanical systems (MEMS), and VLSI devices. Finally, the Instrumentation track specializes in the area of Artificial Intelligence, Robotics, and Industrial Automation. ', 'This program provides a deep knowledge of electronics engineering, enabling students to contribute to technological advancement through research and innovation. It offers three specialization tracks: Communications for network design, Microelectronics for sensor development, and Instrumentation & Control for robotics and automation.', '["Telecommunications Engineer", "Computer Network Engineer", "Biomedical Engineer", "Broadcast Engineer"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-electronics-engineering/'),
	(31, 12, 'Bachelor of Fine Arts, major in Advertising Arts', 'The Advertising Arts major provides the foundation of both the visual design and marketing aspects of advertising. The discipline introduces the student to both aesthetics and promotion in the form of commercial art. In Advertising Arts, students learn not only drawing and rendering skills; but are also developed in the business side of advertising. Moreover, the program also offers elective courses that provide an overview of allied areas in the discipline, such as illustration, fashion design, package design, merchandising, corporate identity, digital arts, animation, and photography. Like any other UST program offering, design development projects in the said program discipline are research-based to support the goal of the college to produce not only talented Thomasian artists but also competent and highly qualified Advertising Arts Practitioners.', 'This program teaches the core principles of visual design and marketing, blending artistic skills with business acumen for the advertising industry. It offers diverse electives and uses research-based projects to produce competent and qualified practitioners.', '["Creative Director", "Media Planner", "Advertising Manager", "Ad Agency Account Executive"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-fine-arts-major-in-advertising-arts/'),
	(32, 12, 'Bachelor of Fine Arts, major in Industrial Design', 'Industrial Design major is an integration of art and technology. It prepares students for a professional career in product design, specializing in the development of manufactured objects and systems design. The program is geared toward generating designers who create innovative, sensible, sustainable, aesthetically suitable, and socially relevant products. ', 'This program merges art and technology to prepare students for careers in product and systems design. It aims to produce designers who create innovative, sustainable, and socially relevant products.', '["Product Designer", "Design Associate", "Furniture Engineer", "Toys and Games Designer"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-fine-arts-major-in-industrial-design/'),
	(33, 12, 'Bachelor of Science in Interior Design', 'Interior Design is the act of planning, designing, specifying, and giving general administration and responsible direction to the functional, orderly and aesthetic arrangements and development of materials of buildings and residences. Bachelor of Science in Interior Design is designed to develop foundational skills to prepare the student for the job. The program focuses on studio and academic research in history, theory and methods as they relate to interdisciplinary approach to interior design.', 'This program teaches the planning and design of functional, orderly, and aesthetic interior spaces. It develops foundational skills through studio work and academic research, preparing students for a professional career.', '["Interior Design Researcher", "Furniture Designer", "Accessories Designer", "Exhibition Designer"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-interior-design/'),
	(34, 18, 'Bachelor of Science in Computer Science', 'Bachelor of Science in Computer Science (BSCS) is a four-year program that includes the study of computing concepts and theories, algorithmic foundations, and new developments in computing. The program prepares its students to design and create algorithmically complex software and develop new and effective algorithms for solving computing problems.', 'This program provides a comprehensive study of computing concepts, theories, and algorithmic foundations. It prepares students to design complex software and develop new, effective algorithms to solve computing problems.', '["Software Engineer", "Applications Software Developer", "Data Analyst", "Systems Analyst"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-computer-science/'),
	(35, 18, 'Bachelor of Science in Information Systems', 'The BS Information Systems program integrates business processes with information technology. Starting Academic Year 2018-2019, the program offers two professional elective tracks: Business Analytics (covering six areas including Fundamentals of Business Analytics, Enterprise Data Management, Analytics Modelling, Analytics Techniques and Tools, Analytics Application, and Analytics Internship with industry immersion) and Service Management (designed to prepare students for careers in the IT-BPO industry with competencies for entry-level positions and career development). Students learn systems analysis, database management, enterprise architecture, and business analytics to become IT professionals who bridge business and technology.', 'This program merges business and technology, teaching systems analysis and database management to create IT professionals who bridge these two areas. It offers specialized tracks in Business Analytics and IT Service Management for careers in data or the IT-BPO industry.', '["Systems Analyst", "Project Leader", "Database Administrator", "Programmer"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-information-systems/'),
	(36, 18, 'Bachelor of Science in Information Technology', 'The BS Information Technology program focuses on the practical application of technology in business and organizational settings. Starting Academic Year 2018-2019, the program offers three professional elective tracks: Network and Security (focusing on CCNA modules, network management, and security policy implementation), Web and Mobile App Development (covering PHP, .NET Framework, Android, iOS, and Windows mobile platforms), and IT Automation (emphasizing hardware integration and Internet of Things applications using technologies like Arduino and Boe-Bot). Students gain expertise in network administration, web development, system maintenance, and emerging technologies.', 'This program focuses on the practical application of technology in business, providing expertise in network administration, web development, and system maintenance. It offers specialized tracks in Network & Security, Web & Mobile App Development, and IT Automation.', '["Computer Engineer", "Network Administrator", "Programmer", "Project Leader"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-information-technology/'),
	(37, 4, 'Bachelor of Science in Basic Human Studies', 'This program is an innovative bachelorÃ¢â‚¬â„¢s degree that serves as a preparatory program for the degree of Doctor of Medicine of the UST Faculty of Medicine and Surgery. An alternative name for the program is Learning-Enhanced Accelerated Program for Medicine (LEAPMed). In terms of course content, the program is more focused on human sciences than any existing premedical courses. At the end of two years and two special terms, the student will exhibit proficiency in basic human sciences and exemplify readiness to pursue medical studies.  Students will graduate with the degree of Bachelor of Science in Basic Human Studies (BSBHS) and will be eligible for admission to Medicine Proper at the UST Faculty of Medicine and Surgery. ', 'This accelerated two-year program provides a focused foundation in human sciences to prepare students for the Doctor of Medicine degree. Graduates earn a Bachelor of Science in Basic Human Studies and are eligible for direct admission to medical school.', '["Clinical Researcher", "Laboratory Assistant", "Physician Associate", "Secondary Education Teacher"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-basic-human-studies/'),
	(38, 17, 'Bachelor of Music in Music Education', 'Bachelor of Music in Music Education prepares a student for a job as Music teacher in Basic Education. Aside from the philosophies and foundations of Education, and strategies used inside the classroom as music teacher, the student is also trained in an instrument of his/her choice as emphasis/major.', 'This program prepares students to become music teachers in basic education by teaching educational philosophies and classroom strategies. Students also receive specialized training on a musical instrument of their choice.', '["Music Teacher", "Cultural Worker", "Researcher"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-music-in-music-education/'),
	(39, 17, 'Bachelor of Music in Music Technology', 'Bachelor of Music in Music Technology is a creative-track course with a strong technology background that introduces the used of computer and music applications in producing music output. The compositional requirement focuses on media and popular music that can be used for television, film, gaming applications, and multi-media. Songwriting is also an area where the student is given training.', 'This program combines creative composition with a strong technological foundation, teaching students to produce music for media like television, film, and gaming. It also provides training in songwriting and the use of computer applications for music production.', '["Media Musician", "Sound Designer", "Sound Effects Specialist", "Music Director"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-music-in-music-technology/'),
	(40, 17, 'Bachelor of Music in Music Theatre', 'Bachelor of Music in Music Theater trains a student to become a performer for musicals of the Broadway genre, Filipino Sarswela and the likes. Students are given training on basic classical, Broadway and jazz style techniques. Dance is an integral part of the program, as well as acting and directing stage musicals.', 'This program trains students to become performers in musical theater, including Broadway and Filipino Sarswela. It provides comprehensive training in singing, dancing, and acting for the stage.', '["Ensemble Performer", "Music Theater Actor", "Music Theater Director"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-music-in-music-theatre/'),
	(41, 13, 'Bachelor of Science in Nursing', 'The BSN Program aims to develop a professional nurse who is able to assume entry-level positions in health facilities or community settings. The professional nurse is capable of providing safe, humane, quality, and holistic care to individuals in varying age, gender, and health-illness status; healthy or at-risk families; population groups; and community; singly or in collaboration with other health care providers, to promote health, prevent illness, restore health, alleviate suffering, and provide end-of-life care.', 'This program prepares nurses for entry-level positions where they can provide safe, humane, and holistic care to individuals, families, and communities. They are trained to promote health, prevent illness, restore health, and alleviate suffering in collaboration with other healthcare providers.', '["Professional Nurse"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-nursing/'),
	(42, 5, 'Bachelor of Science in Biochemistry', 'Biochemistry is the branch of science concerned with the chemistry of biomolecules (proteins, carbohydrates, lipids and nucleic acids) and chemical processes of life. It is multidisciplinary, standing at the crossroads between the physical sciences (chemistry and physics) and the life sciences (botany, zoology, microbiology, and genetics). The BS Biochemistry program offers students the understanding of the structure and function of biomolecules, studying the way these molecules are organized, and the interactions that take place among them in order to maintain life processes.', 'This program explores the chemistry of life by studying the structure and function of biomolecules and their interactions. It is a multidisciplinary field that bridges the physical and life sciences.', '["Doctor of Medicine", "Academic Professor", "Research Institution Scientist", "Forensic Expert"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-biochemistry/'),
	(43, 5, 'Bachelor of Science in Medical Technology', 'Bachelor of Science in Medical Technology is a four-year program consisting of general education and professional courses. The fourth-year level is the one-year internship program in a Commission on Higher Education (CHED)-accredited training laboratory, with rotational duties in different sections, such as Clinical Chemistry, Hematology, Microbiology, Immunohematology (Blood Banking), Immunology and Serology, Urinalysis and other Body Fluids (Clinical Microscopy), Parasitology, Histopathologic/Cytological Techniques, and other emergent technologies. ', 'This four-year program combines general education with professional courses to train students in laboratory science. It culminates in a one-year, CHED-accredited internship with rotations through various clinical laboratory sections.', '["Medical Technologist", "Diagnostic Molecular Scientist", "Research Scientist", "Laboratory Manager"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-medical-technology/'),
	(44, 5, 'Bachelor of Science in Pharmacy', 'Bachelor of Science in Pharmacy is a four-year degree program that equips students with the knowledge and skills necessary for a career in the pharmaceutical field. This comprehensive program encompasses a wide range of coursework and experiential learning to prepare graduates for various roles within the healthcare and pharmaceutical industries. The curriculum of the Bachelor of Science in Pharmacy program is designed to provide students with a solid foundation in pharmaceutical chemistry, practice of pharmacy, pharmaceutics, pharmaceutical sciences, social and administrative pharmacy, and research. Students are exposed to both theoretical and practical aspects of pharmacy, including laboratory work and internship experiences in pharmacy settings. These hands-on experiences allow students to apply their knowledge in real-world situations and develop the skills needed to work effectively as a member of healthcare team. Furthermore, the program emphasizes ethics, patient safety, and regulatory compliance to ensure graduates are well-prepared to uphold the highest standards in pharmaceutical practice. The program aims to produce compassionate Thomasian pharmacists who are morally and scientifically competent and committed to their patientsÃ¢â‚¬â„¢ health and well-being.', 'This four-year program provides comprehensive knowledge and hands-on skills for a career in the pharmaceutical field, covering areas from chemistry to pharmacy practice. It emphasizes ethics, patient safety, and regulatory compliance to produce morally and scientifically competent pharmacists.', '["Pharmaceutical Manufacturing", "Production Planning and Inventory Control", "Clinical Pharmacy", "Research and Development"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-pharmacy/'),
	(45, 20, 'Bachelor of Science in Fitness and Sports Management', 'Bachelor of Science in Fitness and Sports Management is a four-year program designed to provide graduates with a broad and coherent understanding of applied exercise and sports sciences in terms of fitness and sports coaching and the management of fitness and sports programs in various industry settings. This program allows maximum opportunity for students to pursue various combinations of courses in coaching, programming, and administration within their particular areas of interest.', 'This four-year program provides a comprehensive understanding of applied exercise and sports science for careers in coaching and fitness management. It offers students the flexibility to pursue their specific interests within coaching, programming, and administration.', '["Fitness and Recreation Manager", "Sports Tourism Officer", "Sports, Fitness, and Wellness Facilities Manager", "Sports Brand Manager"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-fitness-and-sports-management/'),
	(46, 14, 'Bachelor of Science in Occupational Therapy', 'Bachelor of Science in Occupational Therapy is a four-year program that produces client-centered health professionals who are concerned with promoting health and well-being, with the primary goal of engaging individuals and population in occupation to facilitate participation in culturally meaningful activities and tasks, and address physical, developmental, social, or emotional problems.  The program culminates in a one-year internship program that allows students to work hand in hand with clients of all ages, to increase the latterÃ¢â‚¬â„¢s independence, enhance development, and/or prevent disability through their involvement in activities that are therapeutically designed to promote occupational performance. They also work with different communities and organizations to enable a just and inclusive society for all, in order to facilitate the realization of oneÃ¢â‚¬â„¢s potential in leading an independent, productive, and satisfying life. ', 'This program trains client-centered health professionals who promote well-being by helping individuals engage in meaningful activities to overcome physical and emotional challenges. It includes a one-year internship where students work with clients and communities to enhance independence and foster an inclusive society.', '["Occupational Therapy Consultant", "Clinical Educator"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-occupational-therapy/'),
	(47, 14, 'Bachelor of Science in Physical Therapy', 'Bachelor of Science in Physical Therapy is a four-year program that produces professionals who promote optimal health and function by providing services that develop, maintain, and restore maximum movement and functional ability, for people at any stage of life, when their movement and function are threatened by ageing, injury, diseases, disorders, conditions, or environmental factors. The program culminates in a one-year comprehensive internship program that allows students to work within the health spheres of promotion, prevention, treatment/intervention, habilitation, and rehabilitation, supervised by licensed professionals.', 'This program trains professionals to restore and maintain maximum movement and functional ability in people of all ages. It culminates in a one-year supervised internship covering health promotion, prevention, treatment, and rehabilitation.', '["Physical Therapy Clinician", "Educator", "Researcher", "Consultant"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-physical-therapy/'),
	(48, 14, 'Bachelor of Science in Sports Science', 'Sports Science is an interdisciplinary field designed to provide graduates with a broad and coherent understanding of applied exercise and sports sciences in terms of fitness and sports coaching, and the management of fitness and sports programs in various industry settings. The fitness and sports coaching major is part of a standalone degree, but it enhances and complements the coaching licensure and/or certification accredited by relevant international and national governing sports bodies, as well as fitness-related certifications by reputable organizations in the field. This knowledge and skills base allows graduates to address the relevant needs of employers and pursue further specialization studies. ', 'This interdisciplinary program provides a comprehensive understanding of applied exercise and sports science for careers in coaching and management. It complements professional certifications and equips graduates to meet industry needs or pursue further specialization.', '["Strength and Conditioning Specialist", "Exercise and Sport Specialist", "Fitness and Sports Program Specialist", "Corporate and Commercial Fitness Practitioners"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-sports-science/'),
	(49, 15, 'Bachelor of Science in Microbiology', 'Bachelor of Science in Microbiology is a four-year program that provides its students the opportunity to study the various microorganisms, like viruses, bacteria, algae, protozoan, and fungi, and their activities. The Microbiology program emphasizes the sciences of biology, chemistry, genetics, and mathematics, which are essential to the study of microbiology. In the University of Santo Tomas, the study of microorganisms is done through an inquiry-based and discovery learning process. A degree in microbiology prepares students for graduate-level study, for employment in microbiological and allied fields (e.g., food and beverage industries, health sciences, and environmental sciences), or for medical school.', 'This program provides a comprehensive study of microorganisms like bacteria and viruses through an inquiry-based approach rooted in biology and chemistry. It prepares students for careers in industries such as health and food science, for graduate studies, or for medical school.', '["Microbiologist Scientist", "Medical Product Specialist", "Clinical Research Associate", "Healthcare scientist"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-microbiology/'),
	(50, 15, 'Bachelor of Science in Chemistry', 'Bachelor of Science in Chemistry (BSChem) is a four-year program that aims to produce graduates who comply with the current qualification requirements of professional chemists for local and overseas employment and entrepreneurship. The program aims at building a strong analytical and technical background for employment in a variety of fields. ', 'This four-year program prepares graduates to meet the qualifications for professional chemists in local and international industries or entrepreneurship. It builds a strong analytical and technical foundation for employment in various scientific fields.', '["Laboratory Chemist", "Forensic Chemist", "Research Chemist", "Academic Staff Member"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-chemistry/'),
	(51, 15, 'Bachelor of Science in Psychology', 'The Bachelor of Science in Psychology program is designed to provide students with a Biopsychosocial Model in the study human behavior. This holistic approach gives students the unique perspective of analyzing, interpreting, and exploring the dynamics of human behavior by utilizing concepts in the areas of biology (neuro-anatomy), psychology, and sociology. The Department of Psychology provides a progressive curriculum and research program that offer students the distinct, innovative, and dynamic  opportunity to excel in the practice of psychology, particularly in industrial, educational, and clinical settings.', 'This program uses a holistic Biopsychosocial Model to study human behavior, integrating concepts from biology, psychology, and sociology. Its progressive curriculum prepares students to excel in industrial, educational, and clinical psychology settings.', '["Psychometrician", "Teacher"]', 'https://www.ust.edu.ph/academics/programs/bachelor-of-science-in-psychology/'),
	(52, 16, 'Bachelor of Science in Hospitality Management', 'Bachelor of Science in Hospitality Management prepares graduates to become global leaders and managers for major hospitality industry segments by developing strategies that can be applied at the workplace from running world-class front to back of the house operations, building guest relations, managing financial transactions, creating marketing opportunities to cultivating business ventures. The program aims to achieve its goals and objectives through dynamic academic and research projects and activities geared toward quality life, business success, collaborations, partnerships, creative approaches and conduct of ethical practices. The BS in Hospitality Management program has two areas of specialization: (1) Major in Culinary Entrepreneurship and (2) Major in Hospitality Leadership.', 'This program prepares graduates to be global leaders and managers in the hospitality industry by developing strategic skills for operations, finance, and marketing. It offers specializations in Culinary Entrepreneurship and Hospitality Leadership, achieved through dynamic academic and research projects.', '["Housekeeping Manager", "Resort Hotel Manager", "Baker/Pastry Chef", "Head Cook"]', 'https://www.ust.edu.ph/tourism-and-hospitality-management/'),
	(53, 16, 'Bachelor of Science in Tourism Management', 'Bachelor of Science in Tourism Management is a four-year degree program related to the fields of hospitality and tourism education. It provides students the opportunity to become involved directly in managing and planning the worldÃ¢â‚¬â„¢s biggest people industry Ã¢â‚¬â€œ tourism. This concentrates on courses such as history, travel, language, and other cultural aspects. It provides exposure and training of becoming experts in management of the travel, tour, and hospitality industry and will lead students to a journey toward a senior role in this exciting, diverse, and growing industry. The BS Tourism Management program has two areas of specialization: (1) Major in Travel Operations and Service Management, and (2) Major in Recreation and Leisure Management.', 'This program prepares students to manage and plan within the global tourism industry, focusing on cultural, historical, and travel-related courses. It offers specializations in Travel Operations and Service Management or Recreation and Leisure Management for senior roles in this growing field.', '["Park Management Specialist", "Recreation Specialist", "Flight Attendant", "Manager of Travel Literature"]', 'https://www.ust.edu.ph/tourism-and-hospitality-management/'),
	(54, 8, 'Bachelor of Canon Law', 'The Faculty of Canon Law is primarily open to future members of the diocesan clergy. However, they are also open to religious men and women and lay persons, provided they meet the required qualifications (Sapientia Christiana, art. 31 and UST-Ecclesiastical FacultiesÃ¢â‚¬â„¢ Statutes, art. 21).', 'The Faculty of Canon Law admits qualified clergy, religious, and laypersons with required Church endorsements. Applicants must meet academic standards, show proficiency in English and Latin, and pass the entrance exam, with admission decided by the FacultyÃ¢â‚¬â„¢s Admission Committee.', '["Professor of Canon Law", "Academic Researcher", "Parish Management Consultant"]', 'https://www.ust.edu.ph/canon-law/'),
	(56, 6, 'Bachelor of Philosophy (Classical)', 'The Faculty of Philosophy is primarily open to future members of the diocesan clergy. However, they are also open to religious men and women, provided that they meet the required qualifications (General Statutes, Art. 19.1; Veritatis Gaudium, Art. 31).', 'The Faculty of Philosophy is primarily open to future members of the diocesan clergy. However, they are also open to religious men and women, provided that they meet the required qualifications (General Statutes, Art. 19.1; Veritatis Gaudium, Art. 31).', '["Pastoral Associate", "Academic Researcher", "Educator"]', 'https://www.ust.edu.ph/eccle/students-faculty-of-philosophy/'),
	(57, 7, 'Bachelor in Theology', 'The cyclical courses of study offered in the Faculty of Theology lead to the following degrees: Baccalaureate in Theology (3 years) for the first cycle; Licentiate in Theology (2-5 years) for the second cycle; Doctorate in Theology (2-5 years) for the third cycle. ', 'The cyclical courses of study offered in the Faculty of Theology lead to the following degrees: Baccalaureate in Theology (3 years) for the first cycle; Licentiate in Theology (2-5 years) for the second cycle; Doctorate in Theology (2-5 years) for the third cycle. ', '["Pastoral Associate", "Catechist", "Ordained Ministry"]', 'https://www.ust.edu.ph/academics/programs/bachelor-in-theology/');
